const s=require('./bundlePromotion.service');
const b=v=>v===true||v==='true'?true:v===false||v==='false'?false:undefined;
const wrap=fn=>async(req,res,next)=>{try{await fn(req,res)}catch(e){next(e)}};
exports.listConfigs=wrap(async(req,res)=>{const r=await s.listConfigs({companyId:req.user.companyId,...req.query,isActive:b(req.query.isActive)});res.json({success:true,data:r.rows,pagination:r.pagination})});
exports.getConfigById=wrap(async(req,res)=>res.json({success:true,data:await s.getConfigById({companyId:req.user.companyId,configId:req.params.id})}));
exports.createConfig=wrap(async(req,res)=>res.status(201).json({success:true,message:'Configuration created successfully.',data:await s.createConfig({companyId:req.user.companyId,userId:req.user.id,payload:req.body})}));
exports.updateConfig=wrap(async(req,res)=>res.json({success:true,message:'Configuration updated successfully.',data:await s.updateConfig({companyId:req.user.companyId,configId:req.params.id,userId:req.user.id,payload:req.body})}));
exports.changeConfigStatus=wrap(async(req,res)=>res.json({success:true,message:'Configuration status updated successfully.',data:await s.changeConfigStatus({companyId:req.user.companyId,configId:req.params.id,userId:req.user.id,isActive:req.body.isActive})}));
exports.deleteConfig=wrap(async(req,res)=>res.json({success:true,message:'Configuration deleted successfully.',data:await s.deleteConfig({companyId:req.user.companyId,configId:req.params.id})}));
exports.listBundles=wrap(async(req,res)=>res.json({success:true,data:await s.listBundles({companyId:req.user.companyId,configId:req.params.configId})}));
exports.getBundleById=wrap(async(req,res)=>res.json({success:true,data:await s.getBundleById({companyId:req.user.companyId,bundleId:req.params.bundleId})}));
exports.createBundle=wrap(async(req,res)=>res.status(201).json({success:true,message:'Bundle created successfully.',data:await s.createBundle({companyId:req.user.companyId,configId:req.params.configId,userId:req.user.id,payload:req.body})}));
exports.updateBundle=wrap(async(req,res)=>res.json({success:true,message:'Bundle updated successfully.',data:await s.updateBundle({companyId:req.user.companyId,bundleId:req.params.bundleId,userId:req.user.id,payload:req.body})}));
exports.changeBundleStatus=wrap(async(req,res)=>res.json({success:true,message:'Bundle status updated successfully.',data:await s.changeBundleStatus({companyId:req.user.companyId,bundleId:req.params.bundleId,userId:req.user.id,isActive:req.body.isActive})}));
exports.deleteBundle=wrap(async(req,res)=>res.json({success:true,message:'Bundle deleted successfully.',data:await s.deleteBundle({companyId:req.user.companyId,bundleId:req.params.bundleId})}));
exports.listItems=wrap(async(req,res)=>res.json({success:true,data:await s.listItems({companyId:req.user.companyId,bundleId:req.params.bundleId})}));
exports.getItemById=wrap(async(req,res)=>res.json({success:true,data:await s.getItemById({companyId:req.user.companyId,itemId:req.params.itemId})}));
exports.createItem=wrap(async(req,res)=>res.status(201).json({success:true,message:'Bundle item created successfully.',data:await s.createItem({companyId:req.user.companyId,bundleId:req.params.bundleId,userId:req.user.id,payload:req.body})}));
exports.updateItem=wrap(async(req,res)=>res.json({success:true,message:'Bundle item updated successfully.',data:await s.updateItem({companyId:req.user.companyId,itemId:req.params.itemId,userId:req.user.id,payload:req.body})}));
exports.changeItemStatus=wrap(async(req,res)=>res.json({success:true,message:'Bundle item status updated successfully.',data:await s.changeItemStatus({companyId:req.user.companyId,itemId:req.params.itemId,userId:req.user.id,isActive:req.body.isActive})}));
exports.deleteItem=wrap(async(req,res)=>res.json({success:true,message:'Bundle item deleted successfully.',data:await s.deleteItem({companyId:req.user.companyId,itemId:req.params.itemId})}));
